using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;
namespace KeyJaya {public static class ScriptFeaturesTests {
 static int passed,failed;static void Check(bool value,string name){if(value)passed++;else{failed++;Console.WriteLine("FAIL "+name);}}static void Equal(string expected,string actual,string name){Check(expected==actual,name+" expected="+expected+" actual="+actual);}
 public static int Main(string[] args){string root=Path.Combine(Path.GetDirectoryName(System.Reflection.Assembly.GetExecutingAssembly().Location),"script-feature-test-artifacts",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path.Combine(root,"data"));Directory.CreateDirectory(Configuration.Folder(root));foreach(string file in Directory.GetFiles(Path.Combine(args[0],"data")))File.Copy(file,Path.Combine(root,"data",Path.GetFileName(file)));Configuration.Write(Configuration.Short(root),new Dictionary<string,string>());string settings=Path.Combine(Configuration.Folder(root),"settings.ini"),spellings=Path.Combine(Configuration.Folder(root),"script-spellings.tsv");File.WriteAllText(settings,"custom=keep\n",new UTF8Encoding(false));
 using(Core c=new Core(root)){Check(!c.ScriptOptions.Precise&&!c.ScriptOptions.PreserveVerseMarkers,"defaults common/remove verse markers");foreach(string line in File.ReadLines(args[1])){if(line.StartsWith("#")||line=="")continue;string[] row=line.Split('\t');c.ScriptOptions.Set(row[0]=="precise",false);Equal(row[3],c.ConvertCopied(row[2],row[1]),"reference passage "+row[2]);}
 for(int bits=0;bits<4;bits++){c.ScriptOptions.Set((bits&1)!=0,(bits&2)!=0);using(Core restarted=new Core(root)){Check(restarted.ScriptOptions.Precise==((bits&1)!=0)&&restarted.ScriptOptions.PreserveVerseMarkers==((bits&2)!=0),"independent saved flags");Equal((bits&1)!=0?"कल":"काल",restarted.ConvertCopied("kala","devanagari"),"precise/common default");Equal((bits&2)!=0?"prajāḥ ॥ 6 ॥":"prajāḥ",restarted.ConvertCopied("प्रजा: ॥ ६ ॥","unicode"),"verse marker preference");Equal("12 hi",restarted.ConvertCopied("१२ hi","unicode"),"unrelated number retained");Equal("custom=keep",File.ReadAllLines(settings)[0],"unrelated settings retained");}}
 c.ScriptOptions.Set(false,false);foreach(string form in new[]{"কো","কৈ","কৌ","য়ো","ড়ে"})Equal(IndicScripts.ToIast(form),c.ConvertCopied(form.Normalize(NormalizationForm.FormD),"unicode"),"decomposed Bengali vowel/nukta "+form);Equal("kṣa",c.ConvertCopied("क्\u200dष","unicode"),"script conjunct joiner");Equal("qa",c.ConvertCopied("क़","unicode"),"precomposed Hindi nukta");Equal("qa",c.ConvertCopied("क़","unicode"),"decomposed Hindi nukta");Equal("ye",c.ConvertCopied("য়ে","unicode"),"precomposed Bengali y vowel");Equal("कृष्ण",c.ConvertCopied("k\u200dr\u0323s\u0323n\u0323a","devanagari"),"decomposed diacritics and joiner");Equal("ye",c.ConvertCopied("য়\u200dে","unicode"),"Bengali decomposed nukta and joiner");Equal("कृष्ण\u00a0शक्ति\nकृष्ण",c.ConvertCopied("kṛṣṇa\u00a0śakti\nkṛṣṇa","devanagari"),"NBSP and newline preserved");Equal("कृष्ण शक्ति",c.ConvertCopied("kṛṣṇa\u200bśakti","devanagari"),"zero-width space keeps word boundary");Equal("कृष्ण",c.ConvertCopied("\ufeffkṛ\u2060ṣṇa","devanagari"),"BOM and word joiner cleaned");Equal("https://example.com/kala?x=1",c.ConvertCopied("https://example.com/kala?x=1","devanagari"),"protected URL unchanged");foreach(string mode in new[]{"unicode","balaram","plain","itrans"})Equal("an age since",c.ConvertCopied("an age since",mode),"ordinary English guard remains");}
 File.WriteAllText(spellings,"# custom\nkala\tकला\tকলা\ncustomword\tकृष्ण\t\n",new UTF8Encoding(false));using(Core c=new Core(root)){Equal("कला",c.ConvertCopied("kala","devanagari"),"preferred Devanagari overrides built-in");Equal("কলা",c.ConvertCopied("KALA","bengali"),"preferred Bengali case-insensitive");Equal("कृष्ण",c.ConvertCopied("customword","devanagari"),"unlisted preferred word");c.ScriptOptions.Set(true,false);Equal("कल",c.ConvertCopied("kala","devanagari"),"precise bypasses preferred spelling");c.ScriptOptions.Set(false,false);File.WriteAllText(spellings,"kala\twrong\tকলা\n",new UTF8Encoding(false));try{using(Core bad=Core.Reload(c,root)){}Check(false,"invalid reload rejected");}catch(InvalidDataException){Check(true,"invalid reload rejected");}Equal("कला",c.ConvertCopied("kala","devanagari"),"failed reload retains working core");}
 foreach(string bad in new[]{"x\tक\tक", "x\tक\t\nx\tख\t", "x\t\t", "x\tক\t", "two words\tक\t", "x\tक\tাA"}){File.WriteAllText(spellings,bad+"\n",new UTF8Encoding(false));try{using(Core invalid=new Core(root)){}Check(false,"invalid override rejected "+bad);}catch(InvalidDataException){Check(true,"invalid override rejected");}}
 File.WriteAllText(spellings,"kala\tकला\tকলা\n",new UTF8Encoding(false));string phrases=Path.Combine(Configuration.Folder(root),"script-phrases.tsv");File.WriteAllText(phrases,"kala rang\tकाला रंग\tকালো রং\nkala samay\tकाल समय\tকাল সময়\nkala rang sundar\tकाला रंग सुन्दर\tকালো রং সুন্দর\n",new UTF8Encoding(false));using(Core c=new Core(root)){Equal("काला रंग",c.ConvertCopied("kala rang","devanagari"),"context disambiguates word");Equal("काल समय",c.ConvertCopied("kala samay","devanagari"),"different context uses different spelling");Equal("কালো রং",c.ConvertCopied("KALA RANG","bengali"),"phrase case-insensitive");Equal("काला\tरंग",c.ConvertCopied("kala\trang","devanagari"),"phrase tabs preserved");Equal("কালে",IndicScripts.FromIast("kāle","bengali"),"independent Bengali rendering remains");Equal("काला\u00a0रंग",c.ConvertCopied("kala\u00a0rang","devanagari"),"phrase NBSP preserved");Equal("काला रंग सुन्दर",c.ConvertCopied("kala rang sundar","devanagari"),"longest phrase wins");Equal("कला\n"+c.ConvertCopied("rang","devanagari"),c.ConvertCopied("kala\nrang","devanagari"),"phrase never spans a paragraph");Equal("https://example.com/kala/rang",c.ConvertCopied("https://example.com/kala/rang","devanagari"),"protected URL bypasses phrase matching");Equal("xकला", "x"+c.ConvertCopied("kala","devanagari"),"single-word preference still active");Equal("काला रंग, काल समय!",c.ConvertCopied("kala rang, kala samay!","devanagari"),"multiple phrase matches preserve punctuation");c.ScriptOptions.Set(true,false);Equal("कल रन्ग्",c.ConvertCopied("kala rang","devanagari"),"precise bypasses phrase preferences");c.ScriptOptions.Set(false,false);File.WriteAllText(phrases,"kala rang\twrong target\tকালো রং\n",new UTF8Encoding(false));try{using(Core bad=Core.Reload(c,root)){}Check(false,"invalid phrase reload rejected");}catch(InvalidDataException){Check(true,"invalid phrase reload rejected");}Equal("काला रंग",c.ConvertCopied("kala rang","devanagari"),"invalid phrase reload retains old core");}
 foreach(string invalid in new[]{"kala\tकाल\tকাল", "kala rang\tकाला\tকালো রং", "kala rang\tकाला रंग\tकाल रंग", "kala rang\t\t", "kala rang\tकाला रंग\t\nkala  rang\tकाल रंग\t"}){File.WriteAllText(phrases,invalid+"\n",new UTF8Encoding(false));try{using(Core bad=new Core(root)){}Check(false,"invalid phrase rejected");}catch(InvalidDataException){Check(true,"invalid phrase rejected");}}
 File.WriteAllText(settings,"script_precise=invalid\n",new UTF8Encoding(false));try{new ScriptSettings(settings);Check(false,"invalid setting rejected");}catch(InvalidDataException){Check(true,"invalid setting rejected");}
 Console.WriteLine("PASS: "+passed+" FAIL: "+failed);return failed==0?0:1;}
}}
